assetHelper:
(() => {
  const cache = {};
  window.opus6 = {
    asset(id) {
      if (!cache[id]) {
        const url = (window.__ASSETS__ || {})[id];
        if (!url) return Promise.reject(new Error("No asset \"" + id + "\""));
        cache[id] = new Promise((resolve, reject) => {
          const img = new Image();
          img.onload = () => resolve(img);
          img.onerror = () => reject(new Error("Asset \"" + id + "\" failed to load"));
          img.src = url;
        });
      }
      return cache[id];
    },
    fit(img, mode = "contain", W = 1080, H = 1920) {
      const iw = img.naturalWidth || img.width, ih = img.naturalHeight || img.height;
      const s = mode === "cover" ? Math.max(W / iw, H / ih) : Math.min(W / iw, H / ih);
      return { x: (W - iw * s) / 2, y: (H - ih * s) / 2, s, w: iw * s, h: ih * s };
    },
    toCanvas(f, px, py) { const x = f.x + px * f.s, y = f.y + py * f.s; return Object.assign([x, y], { x, y }); },
  };
})();
